96→    async validateSessionContext(context) {
97→      try {
98→        if (!existsSync(context.worktree)) return { ok: false, reason: 'session worktree no longer exists' };
99→        const root = realpathSync(repoRoot);
100→        const worktree = realpathSync(context.worktree);
101→        const managedRoot = realpathSync(join(repoRoot, '.baton', 'wt'));
102→        if (context.repoRoot && realpathSync(context.repoRoot) !== root) return { ok: false, reason: 'session repository identity mismatch' };
103→        if (worktree !== managedRoot && !worktree.startsWith(`${managedRoot}${sep}`)) return { ok: false, reason: 'session worktree is outside Baton ownership' };
104→        if (context.ownerTaskId && basename(worktree) !== context.ownerTaskId) return { ok: false, reason: 'session worktree owner mismatch' };
105→        const top = execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd: worktree, encoding: 'utf8' }).trim();
106→        if (realpathSync(top) !== worktree) return { ok: false, reason: 'session path is not the recorded git worktree root' };
107→        if (context.branch) {
108→          const branch = execFileSync('git', ['branch', '--show-current'], { cwd: worktree, encoding: 'utf8' }).trim();
109→          if (branch !== context.branch) return { ok: false, reason: 'session worktree branch mismatch' };
110→        }
111→        if (context.baseSha) {
112→          execFileSync('git', ['merge-base', '--is-ancestor', context.baseSha, 'HEAD'], { cwd: worktree, stdio: 'ignore' });
113→        }
114→        return { ok: true };
115→      } catch (err) {
116→        return { ok: false, reason: `session context validation failed: ${err?.message ?? err}` };
117→      }
118→    },
119→    async reconcile() { try { await worktreeMod.reconcile(repoRoot, []); } catch { /* noop */ } },
120→  };
121→}
