1→// worktree.mjs — git-worktree lifecycle mechanics. Everything shells out to a real
2→// `git` binary against a real repo — no git library, no mocking of git itself.
3→//
4→// D7 (spec/RECONCILIATION.md, authoritative) pins the coordinator's ONE dependency
5→// interface as exactly this module's exports: pinBaseSha, createFromBase, captureCommit,
6→// freshVerifySandbox, changedLines, reap, reconcile, listWorktrees (+ markStopped, which
7→// remains a real export per IMPLEMENTATION.md §3 W5 even though D7's literal list omits it).
8→//
9→// Everything this module creates lives under <repoRoot>/.baton/ — `.baton/wt/<taskId>`
10→// for a worker's own worktree, `.baton/verify/<label>-<suffix>` for a throwaway sandbox.
11→// The two directories are structurally namespaced apart (W1).
12→
13→import { execFileSync } from 'node:child_process';
14→import {
15→  cpSync, existsSync, mkdirSync, writeFileSync, readFileSync, rmSync, readdirSync, statSync, lstatSync, realpathSync,
16→} from 'node:fs';
17→import {
18→  join, dirname, isAbsolute, sep, resolve as pathResolve, relative as pathRelative,
19→} from 'node:path';
20→import { randomBytes } from 'node:crypto';
21→
22→// ---------------------------------------------------------------------------
23→// Errors (W7 — typed, never a bare Error wrapping raw stderr)
24→// ---------------------------------------------------------------------------
25→
26→export class DirtyRepoError extends Error {
27→  constructor(message) { super(message); this.name = 'DirtyRepoError'; }
28→}
29→export class BranchAlreadyCheckedOutError extends Error {
30→  constructor(message) { super(message); this.name = 'BranchAlreadyCheckedOutError'; }
31→}
32→export class WorktreeAlreadyExistsError extends Error {
33→  constructor(message) { super(message); this.name = 'WorktreeAlreadyExistsError'; }
34→}
35→export class UnknownWorktreeError extends Error {
36→  constructor(message) { super(message); this.name = 'UnknownWorktreeError'; }
37→}
38→export class InvalidShaError extends Error {
39→  constructor(message) { super(message); this.name = 'InvalidShaError'; }
40→}
41→export class WorktreeLockedError extends Error {
42→  constructor(message) { super(message); this.name = 'WorktreeLockedError'; }
43→}
44→
45→// ---------------------------------------------------------------------------
46→// Internal helpers
47→// ---------------------------------------------------------------------------
48→
49→function sh(cmd, args, cwd) {
50→  return execFileSync(cmd, args, { cwd, encoding: 'utf8' }).trim();
51→}
52→
53→function isClean(dir) {
54→  return sh('git', ['status', '--porcelain'], dir) === '';
55→}
56→
57→function wtDirFor(repoRoot, taskId) {
58→  return join(repoRoot, '.baton', 'wt', taskId);
59→}
60→
61→function metaPathFor(repoRoot, taskId) {
62→  return join(repoRoot, '.baton', 'wt', `${taskId}.meta.json`);
63→}
64→
65→function readMeta(repoRoot, taskId) {
66→  const f = metaPathFor(repoRoot, taskId);
67→  if (!existsSync(f)) return null;
68→  try {
69→    return JSON.parse(readFileSync(f, 'utf8'));
70→  } catch {
71→    return null;
72→  }
73→}
74→
75→function writeMeta(repoRoot, taskId, meta) {
76→  const f = metaPathFor(repoRoot, taskId);
77→  mkdirSync(dirname(f), { recursive: true });
78→  writeFileSync(f, JSON.stringify(meta, null, 2));
79→}
80→
81→function logEvent(opts, worker, kind, payload) {
82→  if (!opts?.log) return;
83→  opts.log.append({ worker, harness: 'n/a', turnEpoch: 0, kind, actor: 'orchestrator', payload });
84→}
85→
86→function dependencySources(repoRoot, dependencyDirs = []) {
87→  const realRepo = realpathSync(repoRoot);
88→  return dependencyDirs.map((rel) => {
89→    if (typeof rel !== 'string' || rel.length === 0 || isAbsolute(rel)) throw new TypeError('dependency directory must be relative');
90→    const source = pathResolve(realRepo, rel); const within = pathRelative(realRepo, source);
91→    if (within === '' || within === '..' || within.startsWith(`..${sep}`) || isAbsolute(within)) throw new TypeError('dependency directory escapes repository');
92→    if (!existsSync(source)) throw new TypeError('dependency directory does not exist');
93→    const realSource = realpathSync(source); const realWithin = pathRelative(realRepo, realSource);
94→    if (realWithin === '..' || realWithin.startsWith(`..${sep}`) || isAbsolute(realWithin) || !lstatSync(realSource).isDirectory()) throw new TypeError('dependency directory is not confined');
95→    return { rel, realSource };
96→  });
97→}
98→
99→function materializeDependencies(dir, sources) {
100→  const copied = [];
101→  for (const { rel, realSource } of sources) {
102→    const target = pathResolve(dir, rel); mkdirSync(dirname(target), { recursive: true });
