12→const stable = (value) => {
13→  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
14→  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
15→  return JSON.stringify(value);
16→};
17→const RUNNER = String.raw`
18→const [targetUrl, exportName, encoded] = process.argv.slice(1);
19→const emit = process.stdout.write.bind(process.stdout);
20→const hardExit = process.exit.bind(process);
21→const removeAllListeners = process.removeAllListeners.bind(process);
22→const parse = JSON.parse.bind(JSON);
23→const arrayIsArray = Array.isArray.bind(Array);
24→const arrayPush = Function.call.bind(Array.prototype.push);
