94→function bounded(items, tokens) {
95→  const out = [];
96→  for (const item of items) {
97→    if (Buffer.byteLength(JSON.stringify([...out, item])) > tokens * 4) break;
98→    out.push(item);
99→  }
100→  return out;
101→}
102→
103→function validatePath(path) {
104→  if (typeof path !== 'string' || path.length === 0 || isAbsolute(path) || path.split(/[\\/]+/).includes('..')) throw typed('behavior target path escapes root', 'path_escape');
105→  if (!['.js', '.mjs'].includes(extname(path).toLowerCase())) throw typed('behavior fingerprint supports dependency-free JavaScript ESM only', 'unsupported_language');
106→  return path;
107→}
108→
109→function target(root, path, maxSourceBytes) {
110→  if (typeof root !== 'string' || root.length === 0) throw new TypeError('behavior root required');
111→  const realRoot = realpathSync(root); let realTarget;
112→  try { realTarget = realpathSync(resolve(realRoot, validatePath(path))); }
113→  catch (error) { if (error?.code === 'path_escape' || error?.code === 'unsupported_language') throw error; throw typed('behavior target unavailable', 'target_unavailable'); }
114→  const rel = relative(realRoot, realTarget);
115→  if (rel === '' || rel === '..' || rel.startsWith(`..${process.platform === 'win32' ? '\\' : '/'}`) || isAbsolute(rel)) throw typed('behavior target escapes root', 'path_escape');
116→  if (!statSync(realTarget).isFile()) throw typed('behavior target must be a file', 'target_unavailable');
117→  const source = readFileSync(realTarget); if (source.byteLength > maxSourceBytes) throw typed('behavior source exceeds deployment budget', 'source_too_large');
118→  return { realTarget, source, sourceDigest: sha(source) };
119→}
